                <div>
                  <div
                    className="w-11 h-11 rounded-full flex items-center justify-center text-sm font-semibold mb-3 text-navy-deep"
                    style={{ background: AVATAR_COLORS[index % AVATAR_COLORS.length] }}
                  >
